<?php
require __DIR__.'/_auth.php';$pdo=admin_db();if(!$pdo)exit('Database unavailable.');$id=(int)($_GET['id']??0);$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';if($action==='delete'&&$id){$pdo->prepare('DELETE FROM redirects WHERE id=?')->execute([$id]);header('Location:/admin/redirects.php');exit;}$old='/'.ltrim(trim($_POST['old_path']??''),'/');$new='/'.ltrim(trim($_POST['new_path']??''),'/');$code=in_array((int)($_POST['status_code']??301),[301,302,307,308],true)?(int)$_POST['status_code']:301;if($id){$st=$pdo->prepare('UPDATE redirects SET old_path=?,new_path=?,status_code=? WHERE id=?');$st->execute([$old,$new,$code,$id]);}else{$st=$pdo->prepare('INSERT INTO redirects(old_path,new_path,status_code,created_at) VALUES(?,?,?,NOW())');$st->execute([$old,$new,$code]);}$msg='Redirect saved.';}$row=null;if($id){$st=$pdo->prepare('SELECT * FROM redirects WHERE id=?');$st->execute([$id]);$row=$st->fetch();}$list=$pdo->query('SELECT * FROM redirects ORDER BY created_at DESC')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/css/style.css"><title>Redirect Manager</title></head><body><main class="section wrap"><div class="section-head"><div><span class="eyebrow dark-text">Technical SEO</span><h1>Redirect Manager</h1></div><a class="btn light" href="/admin/">Dashboard</a></div><?php if($msg):?><p><strong><?=e($msg)?></strong></p><?php endif;?><div class="content-layout"><section><form class="contact-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input name="old_path" value="<?=e($row['old_path']??'')?>" placeholder="/old-url" required><input name="new_path" value="<?=e($row['new_path']??'')?>" placeholder="/new-url" required><select name="status_code"><?php foreach([301,302,307,308] as $c):?><option value="<?=$c?>" <?=($row['status_code']??301)===$c?'selected':''?>><?=$c?></option><?php endforeach;?></select><button class="btn gold">Save Redirect</button><?php if($id):?><button class="btn" name="action" value="delete" onclick="return confirm('Delete redirect?')">Delete</button><?php endif;?></form></section><aside><h2>Existing Redirects</h2><?php foreach($list as $r):?><p><a href="/admin/redirects.php?id=<?=$r['id']?>"><strong><?=e($r['old_path'])?></strong></a><br><small><?=e($r['status_code'])?> → <?=e($r['new_path'])?></small></p><?php endforeach;?></aside></div></main></body></html>
